H=[['希腊 têle → 构词成分 tele-','远处；隔着距离']]
PHONE=H+[['希腊来源 tele- + phōnḗ 声音；近代法、德等语言造词','让声音跨越距离'],['英语 telephone','电话；打电话']]
PATH=H+[['tele- + -pathy〔接希腊 páthos 感受〕','隔着距离感受'],['英语 telepathy','不用常规感官交流思想的所谓能力']]
def D(h,a,b):return h+[[a,b]]
W=[
E('telephone','英 /ˈtelɪfəʊn/；美 /ˈteləfoʊn/','电话；打电话','声音不必靠你对着远方大喊，而被设备转成信号送过去。','tele- 远 + -phone 声音；现代电传声用法与德语 Telephon 等造词相接，较早法语也用相似词名指远距传声装置。',PHONE,'名词可以是设备或通信方式，动词则是给人打电话。如今口语常简化为 phone；词源不要求设备一定有电线。','by telephone；answer the telephone；telephone someone。','telephone 传声音；telegraph 原本传编码的信息或文字，二者的后半段不同。',('We spoke by telephone before meeting in person.','见面之前，我们先通过电话交谈。'),('Please telephone the office if your plans change.','如果计划改变，请打电话通知办公室。'),sources=['https://www.etymonline.com/word/telephone','https://en.wiktionary.org/wiki/telephone#English']),
E('telescope','英 /ˈtelɪskəʊp/；美 /ˈteləskoʊp/','望远镜；伸缩；压缩','让远处的东西进入可观察的视野，是 telescope 最直接的画面；可伸缩镜筒又带出动词义。','tele- 远 + scope 看，来自近代拉丁 tēlescopium，采用希腊来源成分造词。',[H[0],['近代拉丁 tēlescopium〔tele- + scope 看〕','观察远处的仪器'],['英语 telescope','望远镜；像镜筒一样伸缩、压缩']],'不只普通光学望远镜，radio telescope 也用于观测。动词可说部件套叠缩短，也可比喻把长时间内容压缩进短篇幅。','look through a telescope；a radio telescope；telescope into。','microscope 看微小事物；telescope 看远处。telescopic 的伸缩义来自仪器结构，不能一律直译“远看”。',('We looked at the moon through a telescope.','我们通过望远镜观察月亮。'),('The film telescopes twenty years of history into two hours.','这部电影把二十年历史压缩进两个小时。'),sources=['https://www.etymonline.com/word/telescope']),
E('telly','/ˈteli/','电视；电视机〔英式口语〕','说话随意时，把 television 缩短，再加亲切的小尾巴，就像中文说“看电视”时不用正式设备名称。','television 的缩略形式 + -y；这里的 tel- 不是 tell“告诉”。',[H[0],['tele- + 拉丁来源 vision → television','远距离传送图像 → 电视'],['英语 television 缩略 + -y → telly','电视、电视机的口语称呼']],'主要学英式口语电视义。俚语中也可能由 hotel/motel 缩成 telly，那是另一来源；谈节目时通常指电视。','watch telly；on the telly；turn off the telly。','TV 使用范围很广；telly 更有英式随意聊天的感觉。',('There is a good documentary on telly tonight.','今晚电视上有部不错的纪录片。'),('Could you turn the telly down a little?','能把电视声音调小一点吗？'),sources=['https://en.wiktionary.org/wiki/telly#English']),
E('telemetry','英 /tɪˈlemɪtri/；美 /təˈlemətri/','遥测；远程测量数据的传送','仪器在远处测出温度、位置或设备状态，再把读数送回你这里。','tele- 远 + -metry 测量；是现代科学构词，不必先经过英语 meter 这个完整单词。',[H[0],['tele- + -metry〔希腊来源的测量成分〕','从远处取得测量'],['英语 telemetry','遥测技术；传回的测量数据']],'航天、设备监测和软件系统都可用。重点是采集并传回数据，不等于远程操纵设备。','telemetry data；a telemetry system；transmit telemetry。','remote control 是远程发指令；telemetry 是把状态和读数传回来，两者可同时存在。',('The satellite transmitted telemetry to the ground station.','卫星把遥测数据传回地面站。'),('Engineers used telemetry to monitor the equipment during the test.','工程师在测试中利用遥测监控设备状态。'),sources=['https://en.wiktionary.org/wiki/telemetry#English']),
E('telepathy','/təˈlepəθi/','心灵感应；传心术','故事里两个人不说话、不发消息，却直接知道对方的想法；这类设想叫 telepathy。','tele- 远 + -pathy 感受，接希腊 páthos；英语近代造词。',PATH,'说的是据称无需通常感官通道就能传递思想的能力，并非已经确立的日常通信方式。小说中常见，生活中也可夸张说彼此很默契。','communicate by telepathy；a claim of telepathy。','telecommunications 指通过技术进行的远程通信；telepathy 的设定是直接传心，不能混为已证实技术。',('In the novel, the twins communicate by telepathy.','小说中，这对双胞胎通过心灵感应交流。'),('Their perfect timing seemed almost like telepathy.','他们配合的时机如此默契，简直像有心灵感应。'),sources=['https://www.etymonline.com/word/telepathy']),
E('telepathic','/ˌtelɪˈpæθɪk/','心灵感应的；据称能传心的','把 telepathy 变成形容词，用来描写这种交流方式，或故事里拥有这种能力的人。','telepathy 对应 -ic 形容词；词尾 -y 改为 -ic，重音也随之变化。',D(PATH,'英语 telepathy → telepathic','心灵感应 → 心灵感应的'),'telepathic powers 是虚构或声称的传心能力。体育评论中 telepathic understanding 通常只是夸张说配合极其默契。','telepathic communication；telepathic powers；telepathic understanding。','empathetic 是能理解他人的感受；telepathic 是仿佛直接读取或传递思想，二者不是同一能力。',('The story gives its heroine telepathic powers.','故事赋予女主人公心灵感应能力。'),('The two musicians seemed to have a telepathic understanding.','这两位音乐家仿佛心意相通，配合极其默契。'),sources=['https://en.wiktionary.org/wiki/telepathic#English']),
E('radiotelephone','英 /ˌreɪdiəʊˈtelɪfəʊn/；美 /ˌreɪdioʊˈteləfoʊn/','无线电话；无线电话机','telephone 的声音通信改走无线电链路，于是远处的人不必靠一条直接连接的电话线交流。','radio 无线电 + telephone 电话；在已有电话词上明确传输方式。',D(PHONE,'英语 radio + telephone → radiotelephone','电话 → 通过无线电进行的电话通信装置'),'常见于航海、航空或通信技术文字。名词重点是无线电传声，不一定特指今天某一款手机。','a marine radiotelephone；a radiotelephone link。','radio 可泛指无线电或单向广播；radiotelephone 强调供人交谈的声音通信。',('The crew contacted the harbour by radiotelephone.','船员通过无线电话联系了港口。'),('The expedition carried a radiotelephone for communication with the base.','探险队携带无线电话，用于与基地通信。'),sources=['https://www.merriam-webster.com/dictionary/radiotelephone','https://en.wiktionary.org/wiki/radiotelephone#English']),
]
ROOT=dict(id='C1481',meaning='远处；跨越距离',core='TELE = FAR / AT A DISTANCE',image='把声音、图像或测量读数送到远处：telephone 传声音，television 传图像，telemetry 把远处读数送回来。telescope 则帮助眼睛观察远方。',intro='tele- 来自希腊 têle“远”。不少词是近代利用希腊、拉丁成分创造的技术名词，并不是古希腊人已经拥有这些设备。看后半部分，就知道跨越距离的是声音、图像、文字还是测量。',forms='-phone 接声音，-graph 接写与记录，-scope 接观察，-metry 接测量，-pathy 接感受。television 混合希腊来源 tele- 与拉丁来源 vision。telly 是后来的口语缩略，不是另一个独立词根。',branches=[['声音传远','telephone, telephony, radiotelephone'],['图像与观察','television, telly, telescope'],['文字和读数','telegraph, telegram, telemetry'],['想象中的传心','telepathy, telepathic']],contrasts='telemetry 收数据，remote control 发控制指令；telepathy 是所谓心灵感应，不能等同于已确立的通信技术。telephone 与 telegraph 的区别在传声和传信方式。',practice='The team used a telescope to observe the sky and a radiotelephone to contact the base. Telemetry carried the instrument readings back.\n\n团队用望远镜观察天空，用无线电话联系基地；仪器读数通过遥测传回。',words=[w['word'] for w in W]+['television','telegraph','telegram','telephony','telco','telegraphy','telegraphic','telephonic'])
